#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct ListNode {
    int ele;
    struct ListNode* next;
} ListNode;

typedef struct {
    int size;
    ListNode* head;
    ListNode* tail;
} LinkedList;

LinkedList* new_LinkedList();
void addLast_LinkedList(LinkedList* link, int ele);
int removeFirst(LinkedList* link);

int main() {
    LinkedList* dq = new_LinkedList();

    int num;
    while(scanf("%d", &num)) {
        addLast_LinkedList(dq,num);
        if(getchar() != ',') break;
    }

    int len;
    scanf("%d", &len);

    int m;
    scanf("%d", &m);

    LinkedList* output_arr = new_LinkedList();

    int i = 1;
    while(len > 0) {
        int out = removeFirst(dq);

        if(i == m) {
            addLast_LinkedList(output_arr,out);
            m = out;
            i = 1;
            len--;
        } else {
            addLast_LinkedList(dq,out);
            i++;
        }
    }

    char res[100000];

    ListNode* cur = output_arr->head;
    while(cur != NULL) {
        char tmp[10];
        sprintf(tmp, "%d", cur->ele);
        strcat(res, tmp);

        cur = cur->next;

        if(cur != NULL) {
            strcat(res, ",");
        }
    }

    puts(res);

    return 0;
}

LinkedList* new_LinkedList() {
    LinkedList* link = (LinkedList*) malloc(sizeof(LinkedList));

    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void addLast_LinkedList(LinkedList* link, int ele) {
    ListNode* node = (ListNode*) malloc(sizeof(ListNode));

    node->ele = ele;
    node->next = NULL;

    if(link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}

int removeFirst(LinkedList* link) {
    if(link->size == 0) exit(-1);

    ListNode* removed = link->head;

    if(link->size == 1) {
        link->head = NULL;
        link->tail = NULL;
    } else {
        link->head = link->head->next;
    }

    link->size--;

    int res = removed->ele;

    free(removed);

    return res;
}
